import { readFile, writeFile } from "node:fs/promises";

export type Links = Record<string, string>;

export async function loadLinks(file: string): Promise<Links> {
  try {
    return JSON.parse(await readFile(file, "utf8")) as Links;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return {};
    throw err;
  }
}

export async function saveLinks(file: string, links: Links): Promise<void> {
  await writeFile(file, JSON.stringify(links, null, 2) + "\n");
}

import { Hono } from "hono";
import { zValidator } from "@hono/zod-validator";
import { nanoid } from "nanoid";
import { z } from "zod";
import { loadLinks, saveLinks } from "./store.js";

const createLinkSchema = z.object({
  url: z.url({ protocol: /^https?$/ }),
});

export function createApp(dataFile: string) {
  const app = new Hono();

  // Serialize read-modify-write cycles so concurrent POSTs don't drop links.
  let writeQueue: Promise<unknown> = Promise.resolve();

  app.post("/links", zValidator("json", createLinkSchema), async (c) => {
    const { url } = c.req.valid("json");
    const task = writeQueue.then(async () => {
      const links = await loadLinks(dataFile);
      let code = nanoid(8);
      while (Object.hasOwn(links, code)) code = nanoid(8);
      links[code] = url;
      await saveLinks(dataFile, links);
      return code;
    });
    writeQueue = task.catch(() => {});
    const code = await task;
    return c.json({ code, url }, 201);
  });

  app.get("/:code", async (c) => {
    const links = await loadLinks(dataFile);
    const code = c.req.param("code");
    if (!Object.hasOwn(links, code)) {
      return c.json({ error: "Not found" }, 404);
    }
    return c.redirect(links[code], 302);
  });

  return app;
}

import { serve } from "@hono/node-server";
import { createApp } from "./app.js";

const port = Number(process.env.PORT ?? 3000);
const app = createApp(process.env.LINKS_FILE ?? "links.json");

serve({ fetch: app.fetch, port }, (info) => {
  console.log(`linkshort listening on http://localhost:${info.port}`);
});

import { mkdtemp, readFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../src/app.js";

let dir: string;
let dataFile: string;
let app: ReturnType<typeof createApp>;

beforeEach(async () => {
  // Keep test data inside the project folder.
  dir = await mkdtemp(join(import.meta.dirname, ".tmp-"));
  dataFile = join(dir, "links.json");
  app = createApp(dataFile);
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

function postLink(body: unknown) {
  return app.request("/links", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

describe("POST /links", () => {
  it("returns a short code and saves the link to the JSON file", async () => {
    const res = await postLink({ url: "https://example.com/some/long/path" });

    expect(res.status).toBe(201);
    const body = await res.json();
    expect(body.code).toMatch(/^[A-Za-z0-9_-]{8}$/);
    expect(body.url).toBe("https://example.com/some/long/path");

    const saved = JSON.parse(await readFile(dataFile, "utf8"));
    expect(saved).toEqual({ [body.code]: "https://example.com/some/long/path" });
  });

  it("keeps every link when several are created at once", async () => {
    const urls = ["https://a.com", "https://b.com", "https://c.com"];
    const responses = await Promise.all(urls.map((url) => postLink({ url })));

    const saved = JSON.parse(await readFile(dataFile, "utf8"));
    expect(Object.values(saved).sort()).toEqual(urls);
    for (const res of responses) expect(res.status).toBe(201);
  });

  it.each([
    ["a missing url", {}],
    ["a non-url string", { url: "not a url" }],
    ["a non-http scheme", { url: "javascript:alert(1)" }],
  ])("rejects %s with 400", async (_label, body) => {
    const res = await postLink(body);
    expect(res.status).toBe(400);
  });
});

describe("GET /:code", () => {
  it("redirects to the original URL", async () => {
    const created = await postLink({ url: "https://example.com/target" });
    const { code } = await created.json();

    const res = await app.request(`/${code}`);

    expect(res.status).toBe(302);
    expect(res.headers.get("Location")).toBe("https://example.com/target");
  });

  it("returns 404 for an unknown code", async () => {
    const res = await app.request("/doesNotExist");
    expect(res.status).toBe(404);
    expect(await res.json()).toEqual({ error: "Not found" });
  });

  it("returns 404 for codes that match built-in object keys", async () => {
    await postLink({ url: "https://example.com" });
    const res = await app.request("/constructor");
    expect(res.status).toBe(404);
  });
});

